package semester1.practice03.homework;

import java.util.Scanner;

/** Логіка п'яти варіантів ДЗ до практичної №3. */
final class Homework03 {
    private Homework03() { }
    static void run(int task) { semester1.ConsoleOutput.useUtf8();
        try (Scanner s=new Scanner(System.in)) {
            switch(task){case 1->fuel(s);case 2->delivery(s);case 3->credit(s);case 4->climate(s);case 5->quest(s);default->throw new IllegalArgumentException();}
        }
    }
    private static double number(Scanner s,String prompt){System.out.print(prompt);while(!s.hasNextDouble()){System.out.println("Введіть число.");s.next();System.out.print(prompt);}return s.nextDouble();}
    private static int integer(Scanner s,String prompt){System.out.print(prompt);while(!s.hasNextInt()){System.out.println("Введіть ціле число.");s.next();System.out.print(prompt);}return s.nextInt();}
    private static void fuel(Scanner s){double distance=number(s,"Відстань (км): "),consumption=number(s,"Витрата (л/100 км): ");int type=integer(s,"Пальне (1 А-95, 2 дизель, 3 газ): ");if(distance<=0||consumption<=0){System.out.println("Відстань і витрата мають бути додатними.");return;}double price=switch(type){case 1->56.50;case 2->52.80;case 3->29.40;default->-1;};if(price<0){System.out.println("Невідомий тип пального.");return;}double liters=distance*consumption/100,base=liters*price,discount=base>=2000?base*.05:0,finalCost=base-discount;System.out.printf("Потрібно пального: %.2f л%nБазова вартість: %.2f грн%nЗнижка: %.2f грн%nДо сплати: %.2f грн%n",liters,base,discount,finalCost);}
    private static void delivery(Scanner s){double weight=number(s,"Вага (кг): ");int distance=integer(s,"Відстань (км): "),type=integer(s,"Доставка (1 відділення, 2 поштомат, 3 кур'єр): ");s.nextLine();System.out.print("Premium? (так/ні): ");String premium=s.nextLine();if(weight<=0||weight>50||distance<=0){System.out.println("Некоректні вага або відстань.");return;}double base=switch(type){case 1->50;case 2->weight>15?-1:60;case 3->100;default->-1;};if(base<0){System.out.println(type==2?"Поштомат не приймає посилки понад 15 кг.":"Невідомий тип доставки.");return;}double distanceFee=distance<=50?0:distance<=200?35:80,total=base+distanceFee,finalCost=premium.equalsIgnoreCase("так")?total*.8:total;System.out.printf("Базовий тариф: %.2f грн%nДоплата за відстань: %.2f грн%nPremium: %s%nДо сплати: %.2f грн%n",base,distanceFee,premium.equalsIgnoreCase("так")?"-20%":"ні",finalCost);}
    private static void credit(Scanner s){int age=integer(s,"Вік: ");double income=number(s,"Місячний дохід: ");System.out.print("Негативна кредитна історія (true/false): ");boolean bad=s.nextBoolean();double amount=number(s,"Сума кредиту: ");int months=integer(s,"Термін (місяців): ");boolean ageOk=age>=21&&age<=65,historyOk=!bad;boolean affordable=months>0&&((amount/months)<=income*.5);double rate=income>=35000?14.5:21;String reason=ageOk?historyOk?affordable?"СХВАЛЕНО":"Відмова: термін кредиту некоректний або платіж перевищує 50% доходу":"Відмова: виявлено негативну кредитну історію":"Відмова: вік не відповідає критеріям (21-65 років)";System.out.println("Рішення: "+reason);if(ageOk&&historyOk&&affordable)System.out.printf("Платіж/міс: %.2f грн, ставка: %.1f%%, максимум: %.2f грн%n",amount/months,rate,income*.5);}
    private static void climate(Scanner s){double current=number(s,"Поточна температура: "),desired=number(s,"Бажана температура: ");int humidity=integer(s,"Вологість (%%): ");s.nextLine();System.out.print("Сезон (зима/літо/міжсезоння): ");String season=s.nextLine().trim().toLowerCase();int mode=integer(s,"Режим (1 normal, 2 eco, 3 vacation): ");s.nextLine();System.out.print("Вікно відчинене (так/ні): ");boolean window=s.nextLine().trim().equalsIgnoreCase("так");double target=switch(mode){case 1->desired;case 2->{double eco=desired;if(season.equals("зима"))eco=Math.min(eco,20);else if(season.equals("літо"))eco=Math.max(eco,24);yield eco;}case 3->season.equals("зима")?16:28;default->desired;};boolean active=!window&&mode!=3;String action=window?"Систему заблоковано: відчинене вікно":!active?"Режим відсутності: клімат-контроль економить енергію":current<target-0.5?"Опалення УВІМКНЕНО":current>target+0.5?"Охолодження УВІМКНЕНО":"Температура комфортна";String humidifier=humidity<35?"Зволожувач УВІМКНЕНО":humidity>65?"Осушувач УВІМКНЕНО":"Вологість нормальна";System.out.printf("Ціль: %.2f°C%n%s%n%s%n",target,action,window?"Зволожувач також вимкнено":humidifier);}
    private static void quest(Scanner s){System.out.println("=== ВТЕЧА З ТЕМНИЦІ ЧАКЛУНА ===");System.out.print("Ім'я героя: ");String name=s.nextLine();int type=integer(s,"Клас (1 воїн, 2 маг, 3 розбійник): ");String hero=switch(type){case 1->"Воїн";case 2->"Маг";case 3->"Розбійник";default->"Мандрівник";};int hp=type==1?110:type==2?75:90,mana=type==2?50:20,agility=type==3?17:10;System.out.printf("%s %s (HP %d, MP %d, AGI %d)%n",hero,name,hp,mana,agility);s.nextLine();System.out.print("Шлях (північ/схід/захід): ");String way=s.nextLine().trim();int artifacts=0;if(way.equalsIgnoreCase("схід")){System.out.println("Знайдено арсенал. Магія чи сила? (магія/сила)");String choice=s.nextLine().trim();if(choice.equalsIgnoreCase("магія")&&mana>=25||choice.equalsIgnoreCase("сила")&&type==1){artifacts++;hp=Math.min(120,hp+20);System.out.println("Скриня відчинилась, знайдено Амулет Світла (+20 HP).");}else{hp-=20;System.out.println("Пастка завдала 20 шкоди.");}}else if(way.equalsIgnoreCase("північ")&&agility>=12){artifacts++;System.out.println("Спритність допомогла оминути пастку й здобути ключ.");}else{hp-=25;System.out.println("Варта влаштувала засідку: -25 HP.");}boolean victory=hp>0&&(artifacts>0||type==1);System.out.println(victory?"Ворота відчинені — перемога!":"Темниця перемогла цього разу.");System.out.printf("Фінал %s: HP %d, артефакти %d, ранг %s%n",name,Math.max(0,hp),artifacts,victory?"S":"D");}
}
